constexpr int kRowThreads = 256;    // 8 warps x 4 value columns
constexpr int kRowColumns = 32;     // value columns per block
constexpr int kMaxDecays = kRowThreads;
// A slot's threads when each lane holds CW value columns (pool-delta's LANE_COLS): 32 / CW warps.
template <int CW>
constexpr int slot_threads() { return 32 * (kRowColumns / CW); }
constexpr int kPoolConvThreads = 128, kPoolConvSegment = 32, kPoolMaxConv = 8;

template <class T> __device__ __forceinline__ float as_float(T x);
template <> __device__ __forceinline__ float as_float<float>(float x) { return x; }
template <> __device__ __forceinline__ float as_float<__nv_bfloat16>(__nv_bfloat16 x) { return __bfloat162float(x); }
template <> __device__ __forceinline__ float as_float<__half>(__half x) { return __half2float(x); }
template <class T> __device__ __forceinline__ T of_float(float x);
template <> __device__ __forceinline__ float of_float<float>(float x) { return x; }
template <> __device__ __forceinline__ __nv_bfloat16 of_float<__nv_bfloat16>(float x) { return __float2bfloat16_rn(x); }
template <> __device__ __forceinline__ __half of_float<__half>(float x) { return __float2half_rn(x); }

// A token's decay e^l: FP64 exp rounded once to FP32, computed once per token per block so every lane uses the same
// value; the one update expression; the warp's fixed-order reductions of a lane's partial dot products (k . S, q . S
// of 4 columns, and |k|^2, |q|^2, q . k): the core's column-scan blocks (crit_kcore/scan_columns.cuh), the blocks
// recurrent_kernels.cu's column scan uses, so the two keep the same bits.
__device__ __forceinline__ float pool_decay(float l) { return kcore::scan::decay_exact(double(l)); }
using kcore::scan::column_sum;
using kcore::scan::column_sum4;
using kcore::scan::column_sum8;
using kcore::scan::delta_update;

struct Row { int first, count, sequence, kind, slot; };

__device__ __forceinline__ Row row_of(const RowSource& s, int r) {
    Row w;
    if(s.meta) {
        const std::int32_t* m = s.meta + 5 * r;
        w.first = m[0];
        w.count = m[1];
        w.sequence = m[2];
        w.kind = m[3];
        w.slot = m[4];
    } else {   // a commit reads no tokens: starts may be absent
        w.first = s.starts ? s.starts[r] : 0;
        w.count = s.starts ? s.starts[r + 1] - w.first : 0;
        w.slot = int(s.slots[r]);
        w.sequence = s.table[w.slot];
        w.kind = s.kind;
    }
    return w;
}

// One stash half: key [capacity][k_heads][dk], decay [capacity][v_heads], delta [capacity][v_heads][dv].
struct Half { float* key; float* decay; float* delta; };
__host__ __device__ __forceinline__ std::size_t half_floats(const DeltaShape& d, int capacity) {
    return std::size_t(capacity) * (std::size_t(d.k_heads) * d.dk + d.v_heads + std::size_t(d.v_heads) * d.dv);
}
__device__ __forceinline__ Half half_at(const DeltaShape& d, float* stash, int parity, int capacity) {
    Half h;
    h.key = stash + std::size_t(parity) * half_floats(d, capacity);
    h.decay = h.key + std::size_t(capacity) * d.k_heads * d.dk;
    h.delta = h.decay + std::size_t(capacity) * d.v_heads;
    return h;
}

// A lane's tile: key rows lane * R .. + R - 1 of value columns j0 .. j0 + CW - 1 of one head's [dk][dv] state, read and
// written in 4-column (16-byte) pieces; with CW 8 or 16 a lane's pieces of a row are adjacent, so a warp's request
// uses whole 32-byte sectors.
template <int R, int CW = 4>
__device__ __forceinline__ void tile_load(float (&S)[R][CW], const float* head, int dk, int dv, int lane, int j0) {
#pragma unroll
    for(int c = 0; c < CW; c += 4) {
        const int jc = j0 + c;
        const bool wide = (dv & 3) == 0 && jc < dv && (reinterpret_cast<std::uintptr_t>(head) & 15u) == 0;
#pragma unroll
        for(int r = 0; r < R; ++r) {
            const int x = lane * R + r;
            if(x < dk && wide) {
                const float4 v = *reinterpret_cast<const float4*>(head + std::size_t(x) * dv + jc);
                S[r][c] = v.x; S[r][c + 1] = v.y; S[r][c + 2] = v.z; S[r][c + 3] = v.w;
            } else {
#pragma unroll
                for(int j = 0; j < 4; ++j) S[r][c + j] = x < dk && jc + j < dv ? head[std::size_t(x) * dv + jc + j] : 0.f;
            }
        }
    }
}
template <int R, int CW = 4>
__device__ __forceinline__ void tile_store(float* head, const float (&S)[R][CW], int dk, int dv, int lane, int j0) {
#pragma unroll
    for(int c = 0; c < CW; c += 4) {
        const int jc = j0 + c;
        const bool wide = (dv & 3) == 0 && jc < dv && (reinterpret_cast<std::uintptr_t>(head) & 15u) == 0;
#pragma unroll
        for(int r = 0; r < R; ++r) {
            const int x = lane * R + r;
            if(x >= dk) continue;
            if(wide) {
                *reinterpret_cast<float4*>(head + std::size_t(x) * dv + jc) =
                    make_float4(S[r][c], S[r][c + 1], S[r][c + 2], S[r][c + 3]);
            } else {
#pragma unroll
                for(int j = 0; j < 4; ++j)
                    if(jc + j < dv) head[std::size_t(x) * dv + jc + j] = S[r][c + j];
            }
        }
    }
}

// Apply `n` stashed steps of value head h (key head kh) to the tile.
template <int R, int CW = 4>
__device__ __forceinline__ void tile_replay(float (&S)[R][CW], const DeltaShape& d, const Half& from, int n, int h, int kh,
                                            int lane, int j0) {
    for(int t = 0; t < n; ++t) {
        const float e = from.decay[std::size_t(t) * d.v_heads + h];
        const float* kr = from.key + (std::size_t(t) * d.k_heads + kh) * d.dk;
        const float* dr = from.delta + (std::size_t(t) * d.v_heads + h) * d.dv;
        float k[R], delta[CW];
#pragma unroll
        for(int r = 0; r < R; ++r) k[r] = lane * R + r < d.dk ? kr[lane * R + r] : 0.f;
#pragma unroll
        for(int j = 0; j < CW; ++j) delta[j] = j0 + j < d.dv ? dr[j0 + j] : 0.f;
#pragma unroll
        for(int r = 0; r < R; ++r)
#pragma unroll
            for(int j = 0; j < CW; ++j) S[r][j] = delta_update(S[r][j], e, k[r], delta[j]);
    }
}

// The inputs of one token for a lane: its key rows of q and k, its warp's CW value columns of v, and beta.
template <int R, int CW = 4>
struct Token { float k[R], q[R], v[CW], b; };

template <int R, class T, int CW = 4>
__device__ __forceinline__ void token_load(Token<R, CW>& u, const DeltaShape& d, const RowInputs& in, std::int64_t t, int h, int kh,
                                           int lane, int j0) {
    const T* kr = static_cast<const T*>(in.k) + t * in.k_row + kh * in.k_head;
    const T* qr = static_cast<const T*>(in.q) + t * in.q_row + kh * in.q_head;
    const T* vr = static_cast<const T*>(in.v) + t * in.v_row + h * in.v_head;
#pragma unroll
    for(int r = 0; r < R; ++r) {
        const int x = lane * R + r;
        u.k[r] = x < d.dk ? as_float<T>(kr[x]) : 0.f;
        u.q[r] = x < d.dk ? as_float<T>(qr[x]) : 0.f;
    }
#pragma unroll
    for(int j = 0; j < CW; ++j) u.v[j] = j0 + j < d.dv ? as_float<T>(vr[j0 + j]) : 0.f;
    u.b = in.beta[t * in.beta_row + h];
}

// One token: the dot products and norms reduced once, delta, the output and the update. kn receives the normalized
// keys the update used. Every column's sums have the 32-lane butterfly's bits whatever CW (column_sum's reduce-scatter
// pairs the same lanes), so a lane holding 4, 8 or 16 columns computes the same values.
template <int R, int CW = 4>
__device__ __forceinline__ void token_step(float (&S)[R][CW], const Token<R, CW>& u, const RowInputs& in, float e,
                                           float (&kn)[R], float (&delta)[CW], float (&o)[CW]) {
    float a[4] = {0.f, 0.f, 0.f, 0.f}, x[2 * CW];
#pragma unroll
    for(int j = 0; j < 2 * CW; ++j) x[j] = 0.f;
#pragma unroll
    for(int r = 0; r < R; ++r) {
        a[0] = fmaf(u.k[r], u.k[r], a[0]);
        a[1] = fmaf(u.q[r], u.q[r], a[1]);
        a[2] = fmaf(u.q[r], u.k[r], a[2]);
#pragma unroll
        for(int j = 0; j < CW; ++j) {
            x[j] = fmaf(u.k[r], S[r][j], x[j]);
            x[CW + j] = fmaf(u.q[r], S[r][j], x[CW + j]);
        }
    }
    if constexpr(CW == 4) column_sum8(x);
    else column_sum(x);
    column_sum4(a);
    const float ik = in.normalize_keys ? 1.f / sqrtf(a[0] + in.epsilon) : 1.f;
    const float iq = (in.normalize_queries ? 1.f / sqrtf(a[1] + in.epsilon) : 1.f) * in.scale;
    const float qk = a[2] * ik * iq;
#pragma unroll
    for(int j = 0; j < CW; ++j) {
        delta[j] = u.b * (u.v[j] - e * (x[j] * ik));
        o[j] = fmaf(e, x[CW + j] * iq, qk * delta[j]);
    }
#pragma unroll
    for(int r = 0; r < R; ++r) {
        kn[r] = u.k[r] * ik;
#pragma unroll
        for(int j = 0; j < CW; ++j) S[r][j] = delta_update(S[r][j], e, kn[r], delta[j]);
    }
}

// Rows of one layer, block per (value head, SLOTS x 32 value columns, row). A pending count and a stash parity belong
// to each 32 columns (a slot, pool_delta_blocks of them a layer and sequence) whatever the block: 8 warps own a slot's
// columns and read and consume its count, so a call of any configuration continues one of any other. The knobs (the
// pool-delta structure's: SLOTS, PREFETCH, MINB, LANE_COLS) change the grouping and the loads' timing only, never a
// value; the defaults (1, 1, none, 4) are the kernel before knobs. LANE_COLS (CW) is the value columns a lane holds: 4,
// 8 or 16, a slot's 32 columns then taking 8, 4 or 2 warps; the same values (token_step), wider loads, fewer warps
// repeating the keys.
template <int R, class T, int SLOTS, int PREFETCH, int MINB, int CW = 4>
__global__ void __launch_bounds__(slot_threads<CW>() * SLOTS, MINB) pool_delta_kernel(DeltaShape d, RowInputs in,
                                                                                       PoolDelta p, RowSource src) {
    constexpr int kSlotThreads = slot_threads<CW>(), kDecays = kSlotThreads * SLOTS < kMaxDecays ? kSlotThreads * SLOTS
                                                                                                    : kMaxDecays;
    const Row w = row_of(src, blockIdx.z);
    const int h = blockIdx.x, warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const int ratio = d.v_heads / d.k_heads, kh = h / ratio;
    constexpr int kGroupWarps = kSlotThreads / 32;
    const int group = SLOTS == 1 ? 0 : warp / kGroupWarps;
    const int gthread = SLOTS == 1 ? int(threadIdx.x) : int(threadIdx.x) % kSlotThreads;
    const int per_head = SLOTS == 1 ? int(gridDim.y) : (d.dv + kRowColumns - 1) / kRowColumns;
    const int column = SLOTS == 1 ? int(blockIdx.y) : int(blockIdx.y) * SLOTS + group;   // the slot's 32 columns
    const bool active = SLOTS == 1 || column < per_head;   // a group past the head's columns reads and writes nothing
    const int j0 = column * kRowColumns + (SLOTS == 1 ? warp : warp % kGroupWarps) * CW;
    const bool scratched = w.kind == kFinal || w.kind == kCheckpoints || w.kind == kRecompute;
    if(w.sequence < 0 || (scratched && (!p.scratch || w.slot < 0))) {
        // a row of no sequence (an unbound round slot), or of a kind that writes scratch without any: zero outputs, no
        // state read or written
        if(lane == 0)
            for(int t = 0; t < w.count; ++t)
#pragma unroll
                for(int j = 0; j < CW; ++j)
                    if(j0 + j < d.dv) in.out[(w.first + std::int64_t(t)) * in.out_row + std::int64_t(h) * d.dv + j0 + j] = 0.f;
        return;
    }
    // (one slot a block: the expressions from before the knobs, unsigned as there)
    const int blocks = SLOTS == 1 ? d.v_heads * gridDim.y : d.v_heads * per_head;
    const int slot = SLOTS == 1 ? h * gridDim.y + blockIdx.y : h * per_head + column;
    const std::int64_t S_size = std::int64_t(d.v_heads) * d.dk * d.dv, head = std::int64_t(h) * d.dk * d.dv;
    float* live = p.states + w.sequence * p.state_sequence + head;
    float* stash = p.stash + w.sequence * p.stash_sequence;
    std::int32_t* control = p.control + w.sequence * p.control_sequence;
    __shared__ int s_pending[SLOTS], s_parity[SLOTS];
    __shared__ float decay[kMaxDecays];
    float S[R][CW];
    tile_load<R, CW>(S, live, d.dk, d.dv, lane, j0);
    if(gthread == 0) {
        s_pending[group] = active ? min(max(control[slot], 0), p.capacity) : 0;
        s_parity[group] = active ? control[blocks + slot] & 1 : 0;
    }
    __syncthreads();
    const int pending = s_pending[group], parity = s_parity[group];
    const bool stashes = (w.kind == kStash || w.kind == kRecompute) && w.count > 0;
    if(gthread == 0 && active) {   // consumed; a stashing row writes the other half and flips the parity
        control[slot] = 0;
        if(stashes) control[blocks + slot] = parity ^ 1;
    }
    if(pending) {
        tile_replay<R, CW>(S, d, half_at(d, stash, parity, p.capacity), pending, h, kh, lane, j0);
        tile_store<R, CW>(live, S, d.dk, d.dv, lane, j0);
    }
    if(w.kind == kFlush || w.count <= 0) return;
    float* scratch = p.scratch ? p.scratch + std::int64_t(w.slot) * p.scratch_slot : nullptr;
    if(w.kind == kCheckpoints) tile_store<R, CW>(scratch + head, S, d.dk, d.dv, lane, j0);
    if(w.kind == kRecompute) tile_store<R, CW>(scratch + head, S, d.dk, d.dv, lane, j0);
    const Half next = half_at(d, stash, parity ^ 1, p.capacity);
    const bool writes_key = blockIdx.y == 0 && h % ratio == 0 && warp == 0, writes_decay = blockIdx.y == 0 && threadIdx.x == 0;
    Token<R, CW> u;
    if constexpr(PREFETCH != 0) token_load<R, T, CW>(u, d, in, w.first, h, kh, lane, j0);
    for(int t0 = 0; t0 < w.count; t0 += kDecays) {
        __syncthreads();   // the previous pass's readers of decay are done
        if((kSlotThreads * SLOTS <= kDecays || threadIdx.x < kDecays) && t0 + int(threadIdx.x) < w.count)
            decay[threadIdx.x] = pool_decay(in.log_decay[(w.first + t0 + std::int64_t(threadIdx.x)) * in.gate_row + h]);
        __syncthreads();
        for(int t = t0; t < min(w.count, t0 + kDecays); ++t) {
            Token<R, CW> now;
            if constexpr(PREFETCH != 0) {
                now = u;
                if(t + 1 < w.count) token_load<R, T, CW>(u, d, in, w.first + t + 1, h, kh, lane, j0);   // in flight meanwhile
            } else {
                token_load<R, T, CW>(now, d, in, w.first + t, h, kh, lane, j0);
            }
            const float e = decay[t - t0];
            float kn[R], delta[CW], o[CW];
            token_step<R, CW>(S, now, in, e, kn, delta, o);
            const std::int64_t row = w.first + t;
            if(lane == 0)
#pragma unroll
                for(int j = 0; j < CW; ++j)
                    if(j0 + j < d.dv) in.out[row * in.out_row + std::int64_t(h) * d.dv + j0 + j] = o[j];
            if(stashes && t < p.capacity) {
                if(lane == 0)
#pragma unroll
                    for(int j = 0; j < CW; ++j)
                        if(j0 + j < d.dv) next.delta[(std::size_t(t) * d.v_heads + h) * d.dv + j0 + j] = delta[j];
                if(writes_key)
#pragma unroll
                    for(int r = 0; r < R; ++r)
                        if(lane * R + r < d.dk) next.key[(std::size_t(t) * d.k_heads + kh) * d.dk + lane * R + r] = kn[r];
                if(writes_decay) next.decay[std::size_t(t) * d.v_heads + h] = e;
            }
            if(w.kind == kCheckpoints && t < p.capacity)
                tile_store<R, CW>(scratch + (t + 1) * S_size + head, S, d.dk, d.dv, lane, j0);
        }
    }
    if(w.kind == kFinal) tile_store<R, CW>(scratch + head, S, d.dk, d.dv, lane, j0);
}

// kReplay and kFlushPending over every layer: block per (value head, 32 value columns, row), walking the layers.
template <int R>
__global__ void __launch_bounds__(kRowThreads) pool_replay_kernel(DeltaShape d, PoolDelta p, RowSource src, int layers,
                                                                  const std::int64_t* accepted, int columns, int mode) {
    const int r = blockIdx.z;
    const Row w = row_of(src, r);
    if(w.sequence < 0 || (mode == kReplay && w.slot < 0)) return;
    const int h = blockIdx.x, warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const int kh = h / (d.v_heads / d.k_heads), j0 = blockIdx.y * kRowColumns + warp * 4;
    const int blocks = d.v_heads * gridDim.y, slot = h * gridDim.y + blockIdx.y;
    const std::int64_t head = std::int64_t(h) * d.dk * d.dv;
    __shared__ int s_n, s_parity;
    for(int layer = 0; layer < layers; ++layer) {
        float* live = p.states + layer * p.state_layer + w.sequence * p.state_sequence + head;
        float* stash = p.stash + layer * p.stash_layer + w.sequence * p.stash_sequence;
        std::int32_t* control = p.control + layer * p.control_layer + w.sequence * p.control_sequence;
        if(layer) __syncthreads();   // the previous layer's readers of s_n and s_parity are done
        if(threadIdx.x == 0) {
            s_parity = control[blocks + slot] & 1;
            if(mode == kFlushPending) {
                s_n = min(max(control[slot], 0), p.capacity);
            } else {
                const std::int64_t n = accepted[r];
                s_n = int(n < 0 ? 0 : n > columns ? columns : n);
            }
        }
        __syncthreads();
        const int n = s_n, parity = s_parity;
        if(mode == kFlushPending && threadIdx.x == 0) control[slot] = 0;
        if(mode == kFlushPending && !n) continue;
        float S[R][4];
        const float* from = mode == kReplay ? p.scratch + layer * p.scratch_layer + std::int64_t(w.slot) * p.scratch_slot + head
                                            : live;
        tile_load<R>(S, from, d.dk, d.dv, lane, j0);
        tile_replay<R>(S, d, half_at(d, stash, parity, p.capacity), n, h, kh, lane, j0);
        tile_store<R>(live, S, d.dk, d.dv, lane, j0);
    }
}

template <int R>
cudaError_t replay_launch(const DeltaShape& d, const PoolDelta& p, const RowSource& s, int layers, const std::int64_t* accepted,
                          int columns, int mode, cudaStream_t stream) {
    const dim3 grid(d.v_heads, (d.dv + kRowColumns - 1) / kRowColumns, s.rows);
    pool_replay_kernel<R><<<grid, kRowThreads, 0, stream>>>(d, p, s, layers, accepted, columns, mode);
    return cudaGetLastError();
}

// The launch in the pool-delta structure's configuration for its shape and row count (the tuning's).
template <int R, class T>
cudaError_t rows_launch(const DeltaShape& d, const RowInputs& in, const PoolDelta& p, const RowSource& s, cudaStream_t stream) {
    const int per_head = (d.dv + kRowColumns - 1) / kRowColumns;
    switch(crit_lookup_pool_delta(d.k_heads, d.v_heads, d.dk, d.dv, s.rows)) {
#define CRIT_CASE(index, slots, prefetch, minb, lane_cols)                                                            \
    case index: {                                                                                                     \
        const dim3 grid(d.v_heads, (per_head + (slots) - 1) / (slots), s.rows);                                       \
        pool_delta_kernel<R, T, slots, prefetch, minb, lane_cols>                                                     \
            <<<grid, slot_threads<lane_cols>() * (slots), 0, stream>>>(d, in, p, s);                                  \
        return cudaGetLastError();                                                                                    \
    }
        CRIT_CONFIGS_pool_delta(CRIT_CASE)
#undef CRIT_CASE
    default: return cudaErrorInvalidConfiguration;
    }
}

// ---------------------------------------------------------------------------------------------- pool-delta-pipe
// The rows of pool_delta_kernel with its bits (the lane's tile in the same registers, token_step, tile_replay, the
// pending counts and stash parities of each 32 columns), on another schedule: a block of 32 / CW warps runs ITEMS
// slots (value head, 32 value columns, row) one after another, item = (row * v_heads + head) * per_head + column. A
// slot's state tile, its 32 R key rows x 32 columns, is copied into shared memory by cp.async STAGES slots ahead (the
// core's stage_columns: a key row's 128 contiguous bytes by 8 neighbouring threads, its 16-byte chunks swizzled by
// the reading lane, read back by read_columns); the same copy group stages the row's first
// kPipeTokens tokens (q and k of the key head, v of the slot's columns, beta, as stored), and the next slot's pending
// count, parity and decay inputs load into registers while the current slot runs. No load of a slot waits on another
// of its loads (the old schedule read the pending count, synchronized, then loaded the token and the decay, then
// took the exponential), and what is in flight holds no registers, so a block keeps STAGES slots in flight. Mechanism
// after FlashInfer's gated-delta decode (Apache-2.0: its cp.async-staged state tiles, the gate inputs read before the
// barrier); written here for crit's [dk][dv] state layout and its sums, no code adapted.

// A stage: the tile, then kPipeTokens tokens of q and k (32 R elements each, zeros past dk) and v (the slot's 32
// columns, zeros past dv) as T, then their betas. A row's tokens past kPipeTokens load from global memory.
constexpr int kPipeTokens = 8;
template <int R>
constexpr int pipe_token_elements() { return 2 * 32 * R + 32; }
template <int R, class T>
constexpr std::size_t pipe_stage_bytes() {
    return std::size_t(32 * R * 32) * 4 + std::size_t(kPipeTokens) * pipe_token_elements<R>() * sizeof(T) + kPipeTokens * 4;
}

// Stage the first n (<= kPipeTokens) tokens of a row: 16-byte copies where the rows and the shape allow, else loads.
template <int R, class T, int NT>
__device__ __forceinline__ void pipe_stage_tokens(unsigned char* at, const DeltaShape& d, const RowInputs& in,
                                                  std::int64_t first, int n, int h, int kh, int col0) {
    constexpr int E = 16 / int(sizeof(T)), kRow = 32 * R, kTok = pipe_token_elements<R>(), kChunks = kTok / E;
    T* tok = reinterpret_cast<T*>(at);
    float* beta = reinterpret_cast<float*>(at + std::size_t(kPipeTokens) * kTok * sizeof(T));
    const T* q = static_cast<const T*>(in.q) + first * in.q_row + kh * in.q_head;
    const T* k = static_cast<const T*>(in.k) + first * in.k_row + kh * in.k_head;
    const T* v = static_cast<const T*>(in.v) + first * in.v_row + std::int64_t(h) * in.v_head + col0;
    const bool wide = d.dk % E == 0 && d.dv % E == 0 && in.q_row % E == 0 && in.k_row % E == 0 && in.v_row % E == 0 &&
                      ((reinterpret_cast<std::uintptr_t>(q) | reinterpret_cast<std::uintptr_t>(k) |
                        reinterpret_cast<std::uintptr_t>(v)) & 15u) == 0;
    for(int i = int(threadIdx.x); i < n * kChunks; i += NT) {
        const int t = i / kChunks, e = (i % kChunks) * E;   // elements e .. e + E - 1 of token t's [q | k | v]
        const T* from;
        int valid;   // elements of the chunk inside the row (a wide chunk is all in or all out)
        if(e < kRow) {
            from = q + t * in.q_row + e;
            valid = d.dk - e;
        } else if(e < 2 * kRow) {
            from = k + t * in.k_row + (e - kRow);
            valid = d.dk - (e - kRow);
        } else {
            from = v + t * in.v_row + (e - 2 * kRow);
            valid = d.dv - col0 - (e - 2 * kRow);
        }
        T* dst = tok + t * kTok + e;
        if(wide) {
            kcore::cp_async16(dst, valid > 0 ? static_cast<const void*>(from) : in.q, valid > 0);
        } else {
#pragma unroll
            for(int j = 0; j < E; ++j) dst[j] = j < valid ? from[j] : of_float<T>(0.f);
        }
    }
    if(int(threadIdx.x) < n) kcore::cp_async_ca<4>(beta + threadIdx.x, in.beta + (first + threadIdx.x) * in.beta_row + h);
}

// Token t's inputs for a lane from a stage: the values token_load reads.
template <int R, class T, int CW>
__device__ __forceinline__ void pipe_token(Token<R, CW>& u, const unsigned char* at, int t, int lane, int jl) {
    constexpr int kRow = 32 * R, kTok = pipe_token_elements<R>();
    const T* tok = reinterpret_cast<const T*>(at) + t * kTok;
#pragma unroll
    for(int r = 0; r < R; ++r) {
        u.q[r] = as_float<T>(tok[lane * R + r]);
        u.k[r] = as_float<T>(tok[kRow + lane * R + r]);
    }
#pragma unroll
    for(int j = 0; j < CW; ++j) u.v[j] = as_float<T>(tok[2 * kRow + jl + j]);
    u.b = reinterpret_cast<const float*>(at + std::size_t(kPipeTokens) * kTok * sizeof(T))[t];
}

struct PipeSlot { int row, h, column; };
__device__ __forceinline__ PipeSlot pipe_slot(int item, int v_heads, int per_head) {
    const int blocks = v_heads * per_head, rem = item % blocks;
    return {item / blocks, rem / per_head, rem % per_head};
}
__device__ __forceinline__ bool pipe_skips(const Row& w, const PoolDelta& p) {
    const bool scratched = w.kind == kFinal || w.kind == kCheckpoints || w.kind == kRecompute;
    return w.sequence < 0 || (scratched && (!p.scratch || w.slot < 0));
}

template <int R, class T, int CW, int ITEMS, int STAGES, int MINB>
__global__ void __launch_bounds__(slot_threads<CW>(), MINB) pool_delta_pipe_kernel(DeltaShape d, RowInputs in, PoolDelta p,
                                                                                   RowSource src, int per_head, int items) {
    constexpr int kThreads = slot_threads<CW>(), kTile = 32 * R * 32;
    constexpr std::size_t kStage = pipe_stage_bytes<R, T>();
    constexpr int kDecays = kThreads < kMaxDecays ? kThreads : kMaxDecays;
    extern __shared__ float4 pipe_shared[];
    unsigned char* stages = reinterpret_cast<unsigned char*>(pipe_shared);   // [STAGES][kStage]
    __shared__ float decay[2][kDecays];   // by item parity: an item's writers never meet the last one's readers
    const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31, jl = warp * CW;
    const int ratio = d.v_heads / d.k_heads, blocks = d.v_heads * per_head;
    const int first = blockIdx.x * ITEMS, n = min(ITEMS, items - first);
    const std::int64_t S_size = std::int64_t(d.v_heads) * d.dk * d.dv;

    // Stage item i's tile and first tokens into buffer i % STAGES (one commit group per item, empty past the block's).
    auto issue = [&](int i) {
        if(i < n) {
            const PipeSlot s = pipe_slot(first + i, d.v_heads, per_head);
            const Row w = row_of(src, s.row);
            if(!pipe_skips(w, p)) {
                unsigned char* at = stages + (i % STAGES) * kStage;
                kcore::scan::stage_columns<R, kThreads>(reinterpret_cast<float*>(at),
                                        p.states + w.sequence * p.state_sequence + std::int64_t(s.h) * d.dk * d.dv, d.dk,
                                        d.dv, s.column * kRowColumns);
                if(w.kind != kFlush && w.count > 0)
                    pipe_stage_tokens<R, T, kThreads>(at + kTile * 4, d, in, w.first, min(w.count, kPipeTokens), s.h,
                                                      s.h / ratio, s.column * kRowColumns);
            }
        }
        kcore::cp_async_commit();
    };
    // Item i's registers loaded ahead: its row, pending count and parity, and decay inputs.
    struct Ahead { Row w; PipeSlot s; int pending, parity; float log_decay; };
    auto ahead = [&](Ahead& a, int i) {
        a.s = pipe_slot(first + i, d.v_heads, per_head);
        a.w = row_of(src, a.s.row);
        a.pending = 0;
        a.parity = 0;
        a.log_decay = 0.f;
        if(pipe_skips(a.w, p)) return;
        const std::int32_t* control = p.control + a.w.sequence * p.control_sequence;
        const int slot = a.s.h * per_head + a.s.column;
        a.pending = control[slot];
        a.parity = control[blocks + slot];
        if(a.w.kind != kFlush && int(threadIdx.x) < min(a.w.count, kDecays))
            a.log_decay = in.log_decay[(a.w.first + std::int64_t(threadIdx.x)) * in.gate_row + a.s.h];
    };

#pragma unroll
    for(int i = 0; i < STAGES; ++i) issue(i);
    Ahead cur;
    ahead(cur, 0);
    for(int i = 0; i < n; ++i) {
        Ahead next;
        if(i + 1 < n) ahead(next, i + 1);   // in flight while item i runs
        const Row w = cur.w;
        const int h = cur.s.h, kh = h / ratio, column = cur.s.column, j0 = column * kRowColumns + jl;
        const int slot = h * per_head + column;
        float* dec = decay[i & 1];
        const bool skip = pipe_skips(w, p);
        const bool tokens = !skip && w.kind != kFlush && w.count > 0;
        const bool late = tokens && w.count > 1;   // reads staged tokens past the first while it runs (block uniform)
        if(tokens && int(threadIdx.x) < min(w.count, kDecays)) dec[threadIdx.x] = pool_decay(cur.log_decay);
        kcore::cp_async_wait<STAGES - 1>();
        __syncthreads();   // item i's tile, tokens and decays are in shared memory
        const unsigned char* stage = stages + (i % STAGES) * kStage;
        const unsigned char* staged = stage + kTile * 4;
        float S[R][CW];
        Token<R, CW> u;   // the next token: token 0 here, then the next past the staged ones
        if(!skip) kcore::scan::read_columns<R, CW>(S, reinterpret_cast<const float*>(stage), lane, jl);
        if(tokens) pipe_token<R, T, CW>(u, staged, 0, lane, jl);
        if(!late) {   // every lane has what it reads of the buffer: it takes item i + STAGES
            __syncthreads();
            issue(i + STAGES);
        }
        if(skip) {
            // a row of no sequence, or of a kind that writes scratch without any: zero outputs, no state read or written
            if(lane == 0)
                for(int t = 0; t < w.count; ++t)
#pragma unroll
                    for(int j = 0; j < CW; ++j)
                        if(j0 + j < d.dv) in.out[(w.first + std::int64_t(t)) * in.out_row + std::int64_t(h) * d.dv + j0 + j] = 0.f;
        } else {
            const std::int64_t head = std::int64_t(h) * d.dk * d.dv;
            float* live = p.states + w.sequence * p.state_sequence + head;
            float* stash = p.stash + w.sequence * p.stash_sequence;
            std::int32_t* control = p.control + w.sequence * p.control_sequence;
            const int pending = min(max(cur.pending, 0), p.capacity), parity = cur.parity & 1;
            const bool stashes = (w.kind == kStash || w.kind == kRecompute) && w.count > 0;
            if(threadIdx.x == 0) {   // consumed (every thread read it before the barrier above); flipped by a stashing row
                control[slot] = 0;
                if(stashes) control[blocks + slot] = parity ^ 1;
            }
            if(pending) {
                tile_replay<R, CW>(S, d, half_at(d, stash, parity, p.capacity), pending, h, kh, lane, j0);
                tile_store<R, CW>(live, S, d.dk, d.dv, lane, j0);
            }
            if(tokens) {
                float* scratch = p.scratch ? p.scratch + std::int64_t(w.slot) * p.scratch_slot : nullptr;
                if(w.kind == kCheckpoints || w.kind == kRecompute) tile_store<R, CW>(scratch + head, S, d.dk, d.dv, lane, j0);
                const Half nh = half_at(d, stash, parity ^ 1, p.capacity);
                const bool writes_key = column == 0 && h % ratio == 0 && warp == 0, writes_decay = column == 0 && threadIdx.x == 0;
                for(int t0 = 0; t0 < w.count; t0 += kDecays) {
                    if(t0) {   // a row past kDecays tokens: the next pass's decays (uniform in the block)
                        __syncthreads();
                        if(t0 + int(threadIdx.x) < w.count)
                            dec[threadIdx.x] = pool_decay(in.log_decay[(w.first + t0 + std::int64_t(threadIdx.x)) * in.gate_row + h]);
                        __syncthreads();
                    }
                    for(int t = t0; t < min(w.count, t0 + kDecays); ++t) {
                        Token<R, CW> now;
                        if(t == 0 || t >= kPipeTokens) now = u;
                        else pipe_token<R, T, CW>(now, staged, t, lane, jl);
                        if(t + 1 >= kPipeTokens && t + 1 < w.count)   // in flight meanwhile
                            token_load<R, T, CW>(u, d, in, w.first + t + 1, h, kh, lane, j0);
                        const float e = dec[t - t0];
                        float kn[R], delta[CW], o[CW];
                        token_step<R, CW>(S, now, in, e, kn, delta, o);
                        const std::int64_t row = w.first + t;
                        if(lane == 0)
#pragma unroll
                            for(int j = 0; j < CW; ++j)
                                if(j0 + j < d.dv) in.out[row * in.out_row + std::int64_t(h) * d.dv + j0 + j] = o[j];
                        if(stashes && t < p.capacity) {
                            if(lane == 0)
#pragma unroll
                                for(int j = 0; j < CW; ++j)
                                    if(j0 + j < d.dv) nh.delta[(std::size_t(t) * d.v_heads + h) * d.dv + j0 + j] = delta[j];
                            if(writes_key)
#pragma unroll
                                for(int r = 0; r < R; ++r)
                                    if(lane * R + r < d.dk) nh.key[(std::size_t(t) * d.k_heads + kh) * d.dk + lane * R + r] = kn[r];
                            if(writes_decay) nh.decay[std::size_t(t) * d.v_heads + h] = e;
                        }
                        if(w.kind == kCheckpoints && t < p.capacity)
                            tile_store<R, CW>(scratch + (t + 1) * S_size + head, S, d.dk, d.dv, lane, j0);
                    }
                }
                if(w.kind == kFinal) tile_store<R, CW>(scratch + head, S, d.dk, d.dv, lane, j0);
            }
        }
        if(late) {   // the row's staged tokens are read: the buffer takes item i + STAGES
            __syncthreads();
            issue(i + STAGES);
        }
        cur = next;
    }
    kcore::cp_async_wait<0>();   // no copy outlives the block
}

template <int R, class T, int CW, int ITEMS, int STAGES, int MINB>
cudaError_t pipe_launch_config(const DeltaShape& d, const RowInputs& in, const PoolDelta& p, const RowSource& s,
                               cudaStream_t stream) {
    const int per_head = (d.dv + kRowColumns - 1) / kRowColumns;
    const long long items = (long long)s.rows * d.v_heads * per_head;
    if(items > 0x7fffffffLL) return cudaErrorInvalidValue;
    constexpr std::size_t smem = std::size_t(STAGES) * pipe_stage_bytes<R, T>();
    if constexpr(STAGES > 1 && smem > 96 * 1024)   // past a block's shared memory with the decays: one stage
        return pipe_launch_config<R, T, CW, ITEMS, 1, MINB>(d, in, p, s, stream);
    auto kernel = pool_delta_pipe_kernel<R, T, CW, ITEMS, STAGES, MINB>;
    if constexpr(smem > 48 * 1024) {
        static const cudaError_t set = cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, int(smem));
        if(set != cudaSuccess) return set;
    }
    const unsigned grid = unsigned((items + ITEMS - 1) / ITEMS);
    kernel<<<grid, slot_threads<CW>(), smem, stream>>>(d, in, p, s, per_head, int(items));
    return cudaGetLastError();
}

// The launch in the pool-delta-pipe structure's configuration for its shape and row count (the tuning's).
template <int R, class T>
cudaError_t pipe_launch(const DeltaShape& d, const RowInputs& in, const PoolDelta& p, const RowSource& s, cudaStream_t stream) {
    switch(crit_lookup_pool_delta_pipe(d.k_heads, d.v_heads, d.dk, d.dv, s.rows)) {
#define CRIT_CASE(index, lane_cols, items, stages, minb) \
    case index: return pipe_launch_config<R, T, lane_cols, items, stages, minb>(d, in, p, s, stream);
        CRIT_CONFIGS_pool_delta_pipe(CRIT_CASE)
#undef CRIT_CASE
    default: return cudaErrorInvalidConfiguration;
    }
}

// A sweep build (CRIT_SWEEP_BUILD) compiles the bench's BF16 inputs only.
template <int R>
cudaError_t rows_dtype(const DeltaShape& d, const RowInputs& in, const PoolDelta& p, const RowSource& s, bool pipelined,
                       cudaStream_t stream) {
    switch(in.dtype) {
    case Scalar::bf16:
        return pipelined ? pipe_launch<R, __nv_bfloat16>(d, in, p, s, stream) : rows_launch<R, __nv_bfloat16>(d, in, p, s, stream);
#if defined(CRIT_SWEEP_BUILD)
    default: return cudaErrorNotSupported;
#else
    case Scalar::f16: return pipelined ? pipe_launch<R, __half>(d, in, p, s, stream) : rows_launch<R, __half>(d, in, p, s, stream);
    default: return pipelined ? pipe_launch<R, float>(d, in, p, s, stream) : rows_launch<R, float>(d, in, p, s, stream);
#endif
    }
}

int lane_rows(int dk) { return dk <= 32 ? 1 : dk <= 64 ? 2 : dk <= 128 ? 4 : 8; }

bool valid_source(const RowSource& s, bool tokens) {
    return s.rows >= 0 && (s.meta || (s.slots && s.table && (s.starts || !tokens))) && s.rows <= 65535;
}
bool valid_pool(const DeltaShape& d, const PoolDelta& p) {
    return pool_delta_supported(d) && p.states && p.stash && p.control && p.capacity >= 1;
}

// ---------------------------------------------------------------------------------------------- convolution
// A causal depthwise convolution of W taps at dilation D: y[t] = act(b + sum_i w[i] x[t - (W - 1 - i) D]). The window
// holds the last S = (W - 1) D inputs, oldest first, so tap i < W - 1 reads window[i D] and tap W - 1 the input.
template <int W, int D> constexpr int kSpan = (W - 1) * D;

template <int W, int D>
__device__ __forceinline__ float pool_conv_value(const float (&win)[kSpan<W, D>], const float (&w)[W], float b, float xt,
                                                 bool act) {
    float acc = b;
#pragma unroll
    for(int i = 0; i < W - 1; ++i) acc = fmaf(w[i], win[i * D], acc);
    acc = fmaf(w[W - 1], xt, acc);
    return act ? acc / (1.f + expf(-acc)) : acc;
}
template <int W, int D>
__device__ __forceinline__ void pool_conv_shift(float (&win)[kSpan<W, D>], float xt) {
#pragma unroll
    for(int i = 0; i < kSpan<W, D> - 1; ++i) win[i] = win[i + 1];
    win[kSpan<W, D> - 1] = xt;
}

// One layer of one row for one channel: the pending inputs shifted in, then the row's inputs.
template <int W, int D, class T>
__device__ __forceinline__ void conv_layer(const ConvInputs& c, const PoolConv& p, const Row& w, int layer, int ch, int n) {
    constexpr int S = kSpan<W, D>;
    float* window = p.window + layer * p.window_layer + w.sequence * p.window_sequence + std::int64_t(ch) * S;
    const float* stash_in = p.stash + layer * p.stash_layer + w.sequence * p.stash_sequence;
    float win[S];
#pragma unroll
    for(int i = 0; i < S; ++i) win[i] = window[i];
    for(int t = 0; t < n; ++t) pool_conv_shift<W, D>(win, stash_in[std::int64_t(t) * c.channels + ch]);
    if(n)
#pragma unroll
        for(int i = 0; i < S; ++i) window[i] = win[i];
    if(w.kind == kFlush || w.count <= 0) return;
    float wt[W];
#pragma unroll
    for(int i = 0; i < W; ++i) wt[i] = c.weight[std::int64_t(ch) * W + i];
    const float b = c.bias ? c.bias[ch] : 0.f;
    float* stash_out = p.stash + layer * p.stash_layer + w.sequence * p.stash_sequence;
    for(int t = 0; t < w.count; ++t) {
        const std::int64_t row = w.first + t;
        const float xt = as_float<T>(static_cast<const T*>(c.x)[row * c.x_row + ch]);
        static_cast<T*>(c.out)[row * c.out_row + ch] = of_float<T>(pool_conv_value<W, D>(win, wt, b, xt, c.silu));
        pool_conv_shift<W, D>(win, xt);
        if(w.kind == kStash && t < p.capacity) stash_out[std::int64_t(t) * c.channels + ch] = xt;
    }
    if(w.kind == kFinal) {
        float* to = p.scratch + std::int64_t(w.slot) * p.scratch_slot + std::int64_t(ch) * S;
#pragma unroll
        for(int i = 0; i < S; ++i) to[i] = win[i];
    }
}

template <int W, int D, class T>
__global__ void __launch_bounds__(kPoolConvThreads) pool_conv_kernel(ConvInputs c, PoolConv p, RowSource src, int layers) {
    const Row w = row_of(src, blockIdx.y);
    const int ch = blockIdx.x * kPoolConvThreads + threadIdx.x;
    if(w.sequence < 0 || (w.kind == kFinal && (!p.scratch || w.slot < 0))) {
        // a row of no sequence (an unbound round slot), or a FINAL row without scratch: zero outputs, no window read or
        // written
        if(ch < c.channels && w.kind != kFlush)
            for(int t = 0; t < w.count; ++t) static_cast<T*>(c.out)[(w.first + std::int64_t(t)) * c.out_row + ch] = of_float<T>(0.f);
        return;
    }
    // A block walks the layers (a flush of every layer; a forward row has one): each layer's pending count read once.
    __shared__ int s_n;
    for(int layer = 0; layer < layers; ++layer) {
        std::int32_t* pending = p.pending + layer * p.pending_layer + w.sequence * p.pending_sequence + blockIdx.x;
        if(layer) __syncthreads();   // the previous layer's readers of s_n are done
        if(threadIdx.x == 0) {
            s_n = min(max(*pending, 0), p.capacity);
            *pending = 0;
        }
        __syncthreads();
        if(ch < c.channels) conv_layer<W, D, T>(c, p, w, layer, ch, s_n);
    }
}

// One long row, thread per (channel, kPoolConvSegment rows), recurrent_kernels.cu's conv_segments_kernel over pool windows.
template <int W, int D, class T>
__global__ void __launch_bounds__(kPoolConvThreads) conv_segments_kernel(ConvInputs c, const float* window_in, float* window_out,
                                                                         int rows) {
    constexpr int S = kSpan<W, D>;
    const int ch = blockIdx.x * kPoolConvThreads + threadIdx.x, t0 = blockIdx.y * kPoolConvSegment;
    if(ch >= c.channels) return;
    const T* x = static_cast<const T*>(c.x);
    const int n = min(kPoolConvSegment, rows - t0);
    float win[S], wt[W];
#pragma unroll
    for(int i = 0; i < S; ++i) {   // the S inputs before the segment: the row's, or the window's before the row
        const int at = t0 - S + i;
        win[i] = at >= 0 ? as_float<T>(x[std::int64_t(at) * c.x_row + ch]) : window_in[std::int64_t(ch) * S + S + at];
    }
#pragma unroll
    for(int i = 0; i < W; ++i) wt[i] = c.weight[std::int64_t(ch) * W + i];
    const float b = c.bias ? c.bias[ch] : 0.f;
    for(int i = 0; i < n; ++i) {
        const int t = t0 + i;
        const float xt = as_float<T>(x[std::int64_t(t) * c.x_row + ch]);
        static_cast<T*>(c.out)[std::int64_t(t) * c.out_row + ch] = of_float<T>(pool_conv_value<W, D>(win, wt, b, xt, c.silu));
        pool_conv_shift<W, D>(win, xt);
    }
    if(blockIdx.y == 0)
#pragma unroll
        for(int i = 0; i < S; ++i) {   // the last S inputs, from the window where the row is shorter
            const int at = rows - S + i;
            window_out[std::int64_t(ch) * S + i] =
                at >= 0 ? as_float<T>(x[std::int64_t(at) * c.x_row + ch]) : window_in[std::int64_t(ch) * S + S + at];
        }
}

// One sequence's prompt chunk padded to `rows` tokens (a captured graph's bucket): meta [5] on the device (first unused,
// count, sequence, kind unused, slot unused). Thread per (channel, kPoolConvSegment rows): the chunk's first `count`
// rows convolve from the sequence's window after its pending count (segment 0 applies and consumes it; a later segment
// starts past the window's reach, S <= kPoolConvSegment), later rows (padding) output zeros; segment 0 writes the window
// after the count real inputs in place. A sequence below 0 (padding alone) outputs zeros and touches no window. The
// bits of pool_conv's and conv_segments'.
template <int W, int D, class T>
__global__ void __launch_bounds__(kPoolConvThreads) prompt_conv_kernel(ConvInputs c, PoolConv p, const std::int32_t* meta,
                                                                      int rows) {
    constexpr int S = kSpan<W, D>;
    static_assert(S <= kPoolConvSegment, "a segment past the first reads its window from the chunk");
    const int ch = blockIdx.x * kPoolConvThreads + threadIdx.x, t0 = blockIdx.y * kPoolConvSegment;
    const int count = min(max(meta[1], 0), rows), sequence = meta[2];
    const int n = min(kPoolConvSegment, rows - t0);
    T* out = static_cast<T*>(c.out);
    const T* x = static_cast<const T*>(c.x);
    __shared__ int s_n;
    int pending = 0;
    if(sequence >= 0 && blockIdx.y == 0) {   // uniform in the block
        std::int32_t* at = p.pending + sequence * p.pending_sequence + blockIdx.x;
        if(threadIdx.x == 0) s_n = min(max(*at, 0), p.capacity);
        __syncthreads();
        pending = s_n;
        if(threadIdx.x == 0) *at = 0;
    }
    if(ch >= c.channels) return;
    if(sequence < 0) {
        for(int i = 0; i < n; ++i) out[(t0 + std::int64_t(i)) * c.out_row + ch] = of_float<T>(0.f);
        return;
    }
    float* window = p.window + sequence * p.window_sequence + std::int64_t(ch) * S;
    float win[S], start[S], wt[W];
    if(t0 == 0) {
        const float* stash_in = p.stash + sequence * p.stash_sequence;
#pragma unroll
        for(int i = 0; i < S; ++i) win[i] = window[i];
        for(int t = 0; t < pending; ++t) pool_conv_shift<W, D>(win, stash_in[std::int64_t(t) * c.channels + ch]);
    } else {
#pragma unroll
        for(int i = 0; i < S; ++i) win[i] = as_float<T>(x[std::int64_t(t0 - S + i) * c.x_row + ch]);
    }
#pragma unroll
    for(int i = 0; i < S; ++i) start[i] = win[i];
#pragma unroll
    for(int i = 0; i < W; ++i) wt[i] = c.weight[std::int64_t(ch) * W + i];
    const float b = c.bias ? c.bias[ch] : 0.f;
    for(int i = 0; i < n; ++i) {
        const int t = t0 + i;
        if(t < count) {
            const float xt = as_float<T>(x[std::int64_t(t) * c.x_row + ch]);
            out[std::int64_t(t) * c.out_row + ch] = of_float<T>(pool_conv_value<W, D>(win, wt, b, xt, c.silu));
            pool_conv_shift<W, D>(win, xt);
        } else {
            out[std::int64_t(t) * c.out_row + ch] = of_float<T>(0.f);
        }
    }
    if(t0 == 0)
#pragma unroll
        for(int i = 0; i < S; ++i) {   // the last S inputs, from the window where the chunk is shorter
            const int at = count - S + i;
            window[i] = at >= 0 ? as_float<T>(x[std::int64_t(at) * c.x_row + ch]) : start[S + at];
        }
}

// The kernels' (taps, dilation) shapes: 2 .. 8 taps undilated, 2 .. 4 taps at dilation 2 .. 4 (pool_conv_supported).
template <int W_, int D_> struct ConvShape { static constexpr int W = W_, D = D_; };
template <class F>
cudaError_t by_shape(int width, int dilation, F&& f) {
    switch(dilation * 16 + width) {
    case 16 + 2: return f(ConvShape<2, 1>{});
    case 16 + 3: return f(ConvShape<3, 1>{});
    case 16 + 4: return f(ConvShape<4, 1>{});
    case 16 + 5: return f(ConvShape<5, 1>{});
    case 16 + 6: return f(ConvShape<6, 1>{});
    case 16 + 7: return f(ConvShape<7, 1>{});
    case 16 + 8: return f(ConvShape<8, 1>{});
    case 32 + 2: return f(ConvShape<2, 2>{});
    case 32 + 3: return f(ConvShape<3, 2>{});
    case 32 + 4: return f(ConvShape<4, 2>{});
    case 48 + 2: return f(ConvShape<2, 3>{});
    case 48 + 3: return f(ConvShape<3, 3>{});
    case 48 + 4: return f(ConvShape<4, 3>{});
    case 64 + 2: return f(ConvShape<2, 4>{});
    case 64 + 3: return f(ConvShape<3, 4>{});
    case 64 + 4: return f(ConvShape<4, 4>{});
    default: return cudaErrorInvalidValue;
    }
}

template <class T>
cudaError_t conv_typed(const ConvInputs& c, const PoolConv* p, const RowSource* s, int layers, const float* in, float* out,
                       int rows, cudaStream_t stream) {
    const int blocks = (c.channels + kPoolConvThreads - 1) / kPoolConvThreads;
    return by_shape(c.width, c.dilation, [&](auto shape) {
        constexpr int W = decltype(shape)::W, D = decltype(shape)::D;
        if(p) pool_conv_kernel<W, D, T><<<dim3(blocks, s->rows), kPoolConvThreads, 0, stream>>>(c, *p, *s, layers);
        else conv_segments_kernel<W, D, T><<<dim3(blocks, (rows + kPoolConvSegment - 1) / kPoolConvSegment), kPoolConvThreads, 0,
                                             stream>>>(c, in, out, rows);
        return cudaGetLastError();
    });
}
template <class T>
cudaError_t prompt_typed(const ConvInputs& c, const PoolConv& p, const std::int32_t* meta, int rows, cudaStream_t stream) {
    const int blocks = (c.channels + kPoolConvThreads - 1) / kPoolConvThreads;
    return by_shape(c.width, c.dilation, [&](auto shape) {
        constexpr int W = decltype(shape)::W, D = decltype(shape)::D;
        prompt_conv_kernel<W, D, T><<<dim3(blocks, (rows + kPoolConvSegment - 1) / kPoolConvSegment), kPoolConvThreads, 0,
                                      stream>>>(c, p, meta, rows);
        return cudaGetLastError();
    });
}
cudaError_t prompt_dispatch(const ConvInputs& c, const PoolConv& p, const std::int32_t* meta, int rows, cudaStream_t stream) {
    switch(c.dtype) {
    case Scalar::bf16: return prompt_typed<__nv_bfloat16>(c, p, meta, rows, stream);
    case Scalar::f16: return prompt_typed<__half>(c, p, meta, rows, stream);
    default: return prompt_typed<float>(c, p, meta, rows, stream);
    }
}
cudaError_t conv_dispatch(const ConvInputs& c, const PoolConv* p, const RowSource* s, int layers, const float* in, float* out,
                          int rows, cudaStream_t stream) {
    switch(c.dtype) {
    case Scalar::bf16: return conv_typed<__nv_bfloat16>(c, p, s, layers, in, out, rows, stream);
    case Scalar::f16: return conv_typed<__half>(c, p, s, layers, in, out, rows, stream);
    default: return conv_typed<float>(c, p, s, layers, in, out, rows, stream);
    }
}

}  // namespace

bool pool_delta_supported(const DeltaShape& d) {
    return d.k_heads > 0 && d.v_heads > 0 && d.v_heads % d.k_heads == 0 && d.dk >= 1 && d.dk <= 256 && d.dv >= 1 &&
           d.v_heads <= 65535 && (d.dv + kRowColumns - 1) / kRowColumns <= 65535;
}

int pool_delta_blocks(const DeltaShape& d) { return d.v_heads * ((d.dv + kRowColumns - 1) / kRowColumns); }

std::size_t pool_delta_half_floats(const DeltaShape& d, int capacity) { return half_floats(d, capacity); }

cudaError_t enqueue_pool_delta(const DeltaShape& d, const RowInputs& in, const PoolDelta& p, const RowSource& s, cudaStream_t stream,
                               bool pipelined) {
    if(!valid_pool(d, p) || !valid_source(s, true) || !in.q || !in.k || !in.v || !in.log_decay || !in.beta || !in.out)
        return cudaErrorInvalidValue;
    if(!s.rows) return cudaSuccess;
    if(!s.meta && (s.kind == kCheckpoints || s.kind == kRecompute || s.kind == kFinal) && !p.scratch) return cudaErrorInvalidValue;
    switch(lane_rows(d.dk)) {
    case 1: return rows_dtype<1>(d, in, p, s, pipelined, stream);
    case 2: return rows_dtype<2>(d, in, p, s, pipelined, stream);
    case 4: return rows_dtype<4>(d, in, p, s, pipelined, stream);
    default: return rows_dtype<8>(d, in, p, s, pipelined, stream);
    }
}

cudaError_t enqueue_pool_delta_replay(const DeltaShape& d, const PoolDelta& p, const RowSource& s, int layers,
                                      const std::int64_t* accepted, int columns, CommitMode mode, cudaStream_t stream) {
#if defined(CRIT_SWEEP_BUILD)
    return cudaErrorNotSupported;
#else
    if(!valid_pool(d, p) || !valid_source(s, false) || layers < 1 || columns < 0) return cudaErrorInvalidValue;
    if(mode != kReplay && mode != kFlushPending) return cudaErrorInvalidValue;
    if(mode == kReplay && (!accepted || !p.scratch || columns > p.capacity)) return cudaErrorInvalidValue;
    if(!s.rows) return cudaSuccess;
    switch(lane_rows(d.dk)) {
    case 1: return replay_launch<1>(d, p, s, layers, accepted, columns, mode, stream);
    case 2: return replay_launch<2>(d, p, s, layers, accepted, columns, mode, stream);
    case 4: return replay_launch<4>(d, p, s, layers, accepted, columns, mode, stream);
    default: return replay_launch<8>(d, p, s, layers, accepted, columns, mode, stream);
    }
#endif
}

int pool_conv_blocks(int channels) { return channels < 1 ? 0 : (channels + kPoolConvThreads - 1) / kPoolConvThreads; }

bool pool_conv_supported(int width, int dilation) {
    return dilation == 1 ? width >= 2 && width <= kPoolMaxConv : width >= 2 && width <= 4 && dilation >= 2 && dilation <= 4;
}

cudaError_t enqueue_pool_conv(const ConvInputs& c, const PoolConv& p, const RowSource& s, int layers, cudaStream_t stream) {
#if defined(CRIT_SWEEP_BUILD)
    return cudaErrorNotSupported;
#else
    if(!valid_source(s, true) || layers < 1 || c.channels < 1 || !pool_conv_supported(c.width, c.dilation) || !c.weight || !p.window ||
       !p.stash || !p.pending || p.capacity < 1 || (c.x && c.out == c.x))
        return cudaErrorInvalidValue;
    if(!s.rows) return cudaSuccess;
    return conv_dispatch(c, &p, &s, layers, nullptr, nullptr, 0, stream);
#endif
}

cudaError_t enqueue_pool_conv_prompt(const ConvInputs& c, const PoolConv& p, const std::int32_t* meta, int rows,
                                     cudaStream_t stream) {
#if defined(CRIT_SWEEP_BUILD)
    return cudaErrorNotSupported;
#else
    if(rows < 0 || c.channels < 1 || !pool_conv_supported(c.width, c.dilation) || !c.x || !c.out || !c.weight || !p.window ||
       !p.stash || !p.pending || !meta || p.capacity < 1 || c.out == c.x || (rows + kPoolConvSegment - 1) / kPoolConvSegment > 65535)
        return cudaErrorInvalidValue;
    if(!rows) return cudaSuccess;
    return prompt_dispatch(c, p, meta, rows, stream);
#endif
}

cudaError_t enqueue_conv_segments(const ConvInputs& c, const float* window_in, float* window_out, int rows, cudaStream_t stream) {
#if defined(CRIT_SWEEP_BUILD)
    return cudaErrorNotSupported;
#else
    if(rows < 0 || c.channels < 1 || !pool_conv_supported(c.width, c.dilation) || !c.x || !c.out || !c.weight || !window_in ||
       !window_out || c.out == c.x || (rows + kPoolConvSegment - 1) / kPoolConvSegment > 65535)
        return cudaErrorInvalidValue;
    if(!rows) return cudaSuccess;
    return conv_dispatch(c, nullptr, nullptr, 1, window_in, window_out, rows, stream);
#endif
}

}  // namespace crit::recurrent_kernels
